head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _5 : @spec3 중 fixedRow(상단 고정 행 영역) 적용 + 분리 처리 전용. description 은 _1 과 동일, validation 은 분리 사유 1개만 보유.
scwin.tData = {
    "description" : "[gridView > P > mergeCol]<br/>동일값이 연속되는 Cell 이 자동으로 병합될때 대상이 되는 Body Column 의 ID 를 설정합니다.",
    "validation" : [
        "fixedRow 속성으로 고정된 영역에도 적용되며 고정 영역은 분리되어 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  ★ @spec3(fixedRow) 전용 구성 : 고정 Row 영역(fixedRow=2) + 스크롤 영역 양쪽에서 mergeCol 필터가 적용되고
//     고정/스크롤 영역이 분리되어 병합됨을 입증.
//    - fixedRow=2 : 상단 행0~행1 을 '고정 Row 영역' 으로 분리(스크롤해도 상단 고정).
//    - mergeCells="bycol" + mergeCellsFixedRows="bycol" : con_mergeCol 선택 시에만 적용(초기 병합 제거).
//        스크롤 영역(mergeCells)·고정 Row 영역(mergeCellsFixedRows) 양쪽 모두 세로 병합 활성화.
//      (mergeCellsFixedRows 가 never 면 고정 영역은 mergeCol 대상이어도 병합 안 됨 → 양쪽 동일 적용 필수)
//    - con_mergeCol : '' 병합 없음(초기) / col1,col2,col3,col4 (전체 대상) / col2 (col2만)
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // con_ 설정값 수집
    //  - con_mergeCol : '' 병합 없음(초기) / col1,col2,col3,col4 (전체 대상) / col2 (col2만)
    let vMergeCol = con_mergeCol.getValue();

    // 병합 옵션 구성 (fixedRow=2 고정)
    //  ★ 초기 병합 제거 : con_mergeCol 미선택('') 이면 mergeCells 를 적용하지 않아 초기 로드 시 병합 없이 원본만 표시.
    //    옵션 선택 후 재생성 시에만 mergeCells/mergeCellsFixedRows(bycol) 적용 + mergeCol 로 병합 대상 컬럼 지정.
    let properties = {
        dataList: "data:dlt_bind",
        fixedRow: 2,
        defaultCellHeight: 34,
    };
    if (vMergeCol !== '') {
        properties.mergeCells = "bycol";          // 스크롤(비고정) Row 영역 세로 병합
        properties.mergeCellsFixedRows = "bycol"; // 고정 Row 영역 세로 병합(동일 적용)
        properties.mergeCol = vMergeCol;
    }

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + (vMergeCol === '' ? '병합 미적용(초기 - 원본 표시)' : 'mergeCells/mergeCellsFixedRows=bycol, mergeCol=' + vMergeCol) + ', fixedRow=2(행0~행1 고정 Row 영역)"', '', 'label1');

    // dataList 생성 후 병합이 보이도록 데이터 구성
    //  ★ @spec3 분리 처리 검증의 핵심 : 같은 컬럼 값이 고정/스크롤 경계(행1↔행2)를 넘어 이어져도
    //     병합 그룹은 경계에서 끊겨 '각각 따로' 병합되어야 한다.
    //
    //   행 | col1 | col2 | col3 | col4 |  영역
    //   ---+------+------+------+------+--------
    //    0 |  A   |  M   |  P   |  X   |  고정 Row (fixedRow=2)
    //    1 |  A   |  M   |  Q   |  X   |  고정 Row
    //   ---+------+------+------+------+----(경계)----
    //    2 |  A   |  M   |  P   |  X   |  스크롤
    //    3 |  A   |  M   |  P   |  X   |  스크롤
    //    4 |  B   |  M   |  P   |  Y   |  스크롤
    //
    //  · col1(A,A,A,A,B) : 값이 경계를 넘어 행0~행3 연속 동일. bycol 시
    //       → 고정 영역 [행0~행1]=A 병합 / 스크롤 영역 [행2~행3]=A 병합 (행4=B 단독)
    //       → 경계를 넘는 [행0~행3] 단일 병합이 '생기지 않음' = 분리 처리 입증.
    //  · col2(M 전부) : 행0~행4 전부 동일. bycol 시
    //       → 고정 [행0~행1]=M / 스크롤 [행2~행4]=M 으로 분리 병합.
    //  · col3(P,Q,P,P,P) : 고정 영역(P,Q)은 미병합 / 스크롤 [행2~행4]=P 병합.
    //  · col4(X,X,X,X,Y) : 고정 [행0~행1]=X / 스크롤 [행2~행3]=X (행4=Y 단독).
    //     → mergeCol=col2 시 col2 만 양 영역 병합, col1/col3/col4 는 비대상으로 미병합 확인.
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "A", "col2": "M", "col3": "P", "col4": "X" },
        { "col1": "A", "col2": "M", "col3": "Q", "col4": "X" },
        { "col1": "A", "col2": "M", "col3": "P", "col4": "X" },
        { "col1": "A", "col2": "M", "col3": "P", "col4": "X" },
        { "col1": "B", "col2": "M", "col3": "P", "col4": "Y" }
    ], false);

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:380px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCol sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 고정영역 병합 확인 : 각 Body td 의 rowSpan 을 읽어 병합 그룹을 고정 Row 영역(행<fixedRow)·스크롤 영역(행>=fixedRow)으로 구분 출력.
//  ★ @spec3(fixedRow) 검증 :
//     1) 고정 Row 영역에도 mergeCol 병합이 적용되는지(고정영역 적용 O/X)
//     2) 경계(fixedRow)를 넘는 병합 그룹이 없는지(고정/스크롤 분리 처리 O/X)
//     3) mergeCol=col2 시 양 영역 모두 col2 만 병합되고 비대상 컬럼은 미병합인지
scwin.btn_checkMerge_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let fixedRow = Number(target1.options.fixedRow) || 0;
    bottom.setReturnValue("[옵션] mergeCells : " + target1.options.mergeCells + " / mergeCellsFixedRows : " + target1.options.mergeCellsFixedRows + " / mergeCol : " + target1.options.mergeCol + " / fixedRow : " + target1.options.fixedRow);

    // td id 는 그리드 id 기준(target1.id). e.target.id 는 클릭된 버튼 id 라 사용 불가
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    // colIndex → 컬럼 ID 매핑 (col1=0, col2=1, col3=2, col4=3)
    let colIdByIndex = ["col1", "col2", "col3", "col4"];

    let fixedDescs = [];   // 고정 Row 영역 병합 그룹
    let scrollDescs = [];  // 스크롤 영역 병합 그룹
    let crossDescs = [];   // 경계를 넘는 병합 그룹(있으면 분리 처리 위반)
    let mergedColSet = {};
    let fixedMerged = false;
    let scrollMerged = false;

    // 중복 td(고정/스크롤 컨테이너 동일 id 복제) 방지용 : 화면 표시 td 만, (영역,행,열) 키로 1회만 처리
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        // 흡수되어 화면에 표시되지 않는 td 제외
        if (td.style.display === 'none' || getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        if (rs <= 1 && cs <= 1) continue;

        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let val = (td.textContent || "").trim();

        let region = (r < fixedRow) ? "fixed" : "scroll";
        let key = region + "_" + r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        // 병합 앵커가 걸친 컬럼들을 대상 목록에 추가
        for (let cc = c; cc < c + cs; cc++) {
            if (colIdByIndex[cc]) mergedColSet[colIdByIndex[cc]] = true;
        }

        let lastRow = r + rs - 1;
        let desc = "세로병합 " + colIdByIndex[c] + " [행" + r + "~행" + lastRow + "] = '" + val + "'";

        // 세로 병합이 고정/스크롤 경계(fixedRow)를 넘는지 판정
        if (rs > 1 && fixedRow > 0 && r < fixedRow && lastRow >= fixedRow) {
            crossDescs.push(desc);
        } else if (region === "fixed") {
            fixedMerged = true;
            fixedDescs.push(desc);
        } else {
            scrollMerged = true;
            scrollDescs.push(desc);
        }
    }

    let mergedCols = Object.keys(mergedColSet).sort();
    bottom.setReturnValue("병합된 Body Column : " + (mergedCols.length ? mergedCols.join(",") : "없음"));

    bottom.setReturnValue("[고정 Row 영역(행<" + fixedRow + ")] 병합 그룹 " + fixedDescs.length + "개");
    for (let d = 0; d < fixedDescs.length; d++) bottom.setReturnValue("  " + fixedDescs[d]);

    bottom.setReturnValue("[스크롤 영역(행>=" + fixedRow + ")] 병합 그룹 " + scrollDescs.length + "개");
    for (let d = 0; d < scrollDescs.length; d++) bottom.setReturnValue("  " + scrollDescs[d]);

    // @spec3 분리 처리 : 경계를 넘는 병합이 없어야 함
    if (crossDescs.length === 0) {
        bottom.setReturnValue("고정/스크롤 분리 처리 : O (경계 넘는 병합 없음)");
    } else {
        bottom.setReturnValue("고정/스크롤 분리 처리 : X (경계 넘는 병합 " + crossDescs.length + "개 발견)");
        for (let d = 0; d < crossDescs.length; d++) bottom.setReturnValue("  (경계초과) " + crossDescs[d]);
    }
    bottom.setReturnValue("고정 Row 영역 병합 적용 여부 : " + fixedMerged + " / 스크롤 영역 병합 적용 여부 : " + scrollMerged);
}
